entries[83787] = { ["name"] = "Plans: Ghost Reaver's Breastplate", ["text"] = "Binds when picked up\nUse: Teaches you how to forge a Ghost Reaver's Breastplate.\nRequires Pandaria Blacksmithing (75)\nRequires The Klaxxi\n- Honored\n\nGhost Reaver's Breastplate\nBinds when equipped\nChest Plate\n16 Armor\n+2 [Strength or Intellect]\n+6 Stamina\n+ 1 Critical Strike\n+ 4 Mastery\n\nPrismatic Socket\nPrismatic Socket\nSocket Bonus: + 4 Strength\n\nDurability 165 / 165\nSell Price:\nRequires Living Steel (8), Spirit of Harmony (8)\nOptional Reagents: Optional Reagent Slot (#49)" }
