entries[83931] = { ["name"] = "Design: Ruby Panther", ["text"] = "Binds when picked up\nUse: Teaches you how to create a Ruby Panther.\nRequires Pandaria Jewelcrafting (75)\nRequires Order of the Cloud Serpent\n- Revered\nSell Price:\nRuby Panther\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount will fly or run, depending on your riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Legends say that an ancient pandaren emperor crafted the first jeweled panther for his son after the boy's twin brother died of an illness.\"\nProfession:\nJewelcraftingRequires Orb of Mystery , Primordial Ruby (20), Living Steel (4), Serpent's Eye (2)" }
entries[83932] = { ["name"] = "Design: Sapphire Panther", ["text"] = "Binds when picked up\nUse: Teaches you how to create a Sapphire Panther.\nRequires Pandaria Jewelcrafting (75)\nRequires Order of the Cloud Serpent\n- Revered\nSell Price:\nSapphire Panther\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount will fly or run, depending on your riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Legends say that an ancient pandaren emperor crafted the first jeweled panther for his son after the boy's twin brother died of an illness.\"\nProfession:\nJewelcraftingRequires Orb of Mystery , River's Heart (20), Living Steel (4), Serpent's Eye (2)" }
