entries[84158] = { ["name"] = "Plans: Contender's Revenant Belt", ["text"] = "Binds when picked up\nUse: Teaches you how to forge a Contender's Revenant Belt.\nRequires Pandaria Blacksmithing (50)\n\nContender's Revenant Belt\nSeason 12\nBinds when equipped\nWaist Plate\n9 Armor\n+3 [Strength or Intellect]\n+5 Stamina\n+ 3 Critical Strike\n+ 3 Mastery\nDurability 50 / 50\n\nContender's Defense (0/8)\nContender's Shoulders\nContender's Leggings\nContender's Helm\nContender's Gloves\nContender's Chestguard\nContender's Bracers\nContender's Boots\nContender's Belt\nSell Price:\nRequires Ghost Iron Bar (7)\nOptional Reagents: Optional Reagent Slot (#49)" }
