entries[84196] = { ["name"] = "Plans: Living Steel Belt Buckle", ["text"] = "Binds when picked up\nUse: Teaches you how to forge a Living Steel Buckle.\nCannot be applied to items higher than level 49.\nRequires Pandaria Blacksmithing (75)\nRequires The Klaxxi\n- Honored\n\nLiving Steel Belt Buckle\nUse: Permanently attach a living steel belt buckle onto a belt, adding a socket to the belt.\n\nAttaching the belt buckle causes the item to become soulbound. Cannot be applied to items higher than level 0.\nSell Price:\nRequires Living Steel" }
entries[84197] = { ["name"] = "Plans: Masterwork Forgewire Axe", ["text"] = "Binds when picked up\nUse: Teaches you how to forge a Masterwork Forgewire Axe.\nRequires Pandaria Blacksmithing (50)\nRequires The Klaxxi\n- Honored\n\nMasterwork Forgewire Axe\nBinds when equipped\nOne-Hand Axe\n1 - 4 Damage Speed 2.60\n(1.0 damage per second)\n+12 Intellect\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\nDurability 90 / 90\nSell Price:\nRequires Ghost Iron Bar (12), Spirit of Harmony (5), Kyparite (30)\nOptional Reagents: Optional Reagent Slot (#48)" }
